  selected=DATA[0];
  function esc(v){return String(v==null?'':v).replace(/[&<>\"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c];});}
  function tone(s,k){s=(s+' '+k).toLowerCase();if(/strategic|warhead|publicly reported/.test(s))return'strategic';if(/construction|commissioning|licensing|development/.test(s))return'building';return'operating';}
  function isActive(){try{var a=window.niyActive?window.niyActive():null;if(a&&a.feature===FEATURE)return true;}catch(e){}try{if(typeof activeTier!=='undefined'&&typeof activeIndex!=='undefined'&&typeof FEATURE_DATA!=='undefined'){var f=(FEATURE_DATA[activeTier]||[])[activeIndex];if(f&&f.feature===FEATURE)return true;}}catch(e){}var x=document.querySelector('#sidebarList .feat-item.active .label');return !!(x&&x.textContent.replace(/\s*(AI|BETA)\s*$/,'').trim()===FEATURE);}
  function countBy(key){var m={};DATA.forEach(function(p){var v=p[key]||'Other';m[v]=(m[v]||0)+1;});return m;}
  function options(key,label){return'<option value="">'+label+'</option>'+Object.keys(countBy(key)).sort().map(function(v){return'<option value="'+esc(v)+'">'+esc(v)+'</option>';}).join('');}
  function feedRows(list){return list.map(function(p){return'<tr data-nww-id="'+esc(p.id)+'" data-nww-drag="1" draggable="true" tabindex="0" role="button"><td><div class="nww-facility"><i class="nww-dot"></i><div><strong title="'+esc(p.name)+'">'+esc(p.name)+'</strong><small>'+esc(p.country)+'</small></div></div></td><td><div class="nww-cell"><strong title="'+esc(p.kind)+'">'+esc(p.kind)+'</strong><small>'+esc(p.region)+'</small></div></td><td><span class="nww-status" data-tone="'+tone(p.status,p.kind)+'">'+esc(p.status)+'</span></td><td><div class="nww-record"><strong>'+esc(p.sourceLabel)+'</strong><span title="'+esc(p.latest)+'">'+esc(p.latest)+'</span><small>Checked '+esc(p.checked)+'</small></div></td></tr>';}).join('');}
  function feedHtml(){var countries=Object.keys(countBy('country')).length;return'<section class="nww-feedbar"><div><h2>Nuclear Watch</h2><p>Public-source civilian and strategic nuclear facility register</p></div><span class="nww-feed-meta"><b data-nww-count>'+DATA.length+'</b> records · '+countries+' countries</span></section><div class="nww-global-strip"><div><label>Power reactors</label><strong>417 operating</strong><span>IAEA PRIS · 26 Jul 2026</span></div><div><label>Reactor pipeline</label><strong>77 building</strong><span>21 suspended · IAEA PRIS</span></div><div><label>Identified uranium</label><strong>7.9345M tU</strong><span>&lt; USD 260/kgU · Red Book 2024</span></div><div><label>Global inventory</label><strong>12,187 warheads</strong><span>SIPRI estimate · Jan 2026</span></div></div><div class="nww-filters"><input class="nww-search" type="search" placeholder="Search facility, country, operator or material"><select class="nww-select nww-kind">'+options('kind','All facility classes')+'</select><select class="nww-select nww-region">'+options('region','All regions')+'</select><select class="nww-select nww-status-filter">'+options('status','All recorded statuses')+'</select></div><div class="nww-feednote"><span>Public facility and country-resource records</span><span>Click for Event Analytics · drag to AI Research</span></div><div class="nww-tablewrap"><table class="nww-table"><colgroup><col style="width:31%"><col style="width:25%"><col style="width:16%"><col style="width:28%"></colgroup><thead><tr><th>Facility / country</th><th>Class / region</th><th>Recorded status</th><th>Latest source record</th></tr></thead><tbody>'+feedRows(DATA)+'</tbody></table></div>';}
  function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
  function project(lat,lon,z){var size=256*Math.pow(2,z),s=Math.sin(clamp(lat,-85.05112878,85.05112878)*Math.PI/180);return{x:(lon+180)/360*size,y:(.5-Math.log((1+s)/(1-s))/(4*Math.PI))*size};}
  function unproject(x,y,z){var size=256*Math.pow(2,z),lon=x/size*360-180,n=Math.PI-2*Math.PI*y/size;return{lat:180/Math.PI*Math.atan(.5*(Math.exp(n)-Math.exp(-n))),lon:lon};}
  function zoomFor(p){if(/country centroid/i.test(p.precision))return 4;if(/approximate|regional/i.test(p.precision))return 8;if(/mine|power reactor|research reactor|facility|complex|site/i.test(p.kind))return 11;return 9;}
  function coordText(p){var d=/approximate|regional|country/i.test(p.precision)?2:4;return Number(p.lat).toFixed(d)+', '+Number(p.lon).toFixed(d);}
  function mapHtml(p){return'<div class="nww-mapwrap"><div class="nww-map" data-nww-map="1" tabindex="0" role="application" aria-label="Interactive public-source map centred on '+esc(p.name)+'"><div class="nww-map-tiles"></div><div class="nww-map-offline">Map tiles unavailable · public coordinates remain active</div><div class="nww-map-markers"></div><span class="nww-map-label">'+esc(p.name)+' · '+esc(coordText(p))+'<br>'+esc(p.precision)+'</span><div class="nww-map-controls"><button type="button" data-nww-map-action="in" aria-label="Zoom in">+</button><button type="button" data-nww-map-action="out" aria-label="Zoom out">−</button><button type="button" class="nww-home" data-nww-map-action="selected">Selected</button></div><div class="nww-map-key"><i></i>selected · drag or scroll · click any visible facility</div><a class="nww-map-attrib" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors · ODbL</a></div></div>';}
  function initMap(root,p){if(!root||!p)return null;var tiles=root.querySelector('.nww-map-tiles'),markers=root.querySelector('.nww-map-markers'),offline=root.querySelector('.nww-map-offline'),state={lat:+p.lat,lon:+p.lon,zoom:zoomFor(p),drag:null,fail:0};function dims(){var r=root.getBoundingClientRect();return{w:Math.max(320,Math.round(r.width)),h:Math.max(220,Math.round(r.height))};}function center(x,y){var q=unproject(x,y,state.zoom);state.lat=clamp(q.lat,-85,85);state.lon=((q.lon+540)%360)-180;}function draw(){var d=dims(),z=state.zoom,n=Math.pow(2,z),c=project(state.lat,state.lon,z),left=c.x-d.w/2,top=c.y-d.h/2,minX=Math.floor(left/256),maxX=Math.floor((left+d.w)/256),minY=Math.max(0,Math.floor(top/256)),maxY=Math.min(n-1,Math.floor((top+d.h)/256));tiles.innerHTML='';state.fail=0;offline.style.display='none';for(var ty=minY;ty<=maxY;ty++)for(var tx=minX;tx<=maxX;tx++){var w=((tx%n)+n)%n,img=document.createElement('img');img.alt='';img.decoding='async';img.referrerPolicy='strict-origin-when-cross-origin';img.src='https://tile.openstreetmap.org/'+z+'/'+w+'/'+ty+'.png';img.style.left=Math.round(tx*256-left)+'px';img.style.top=Math.round(ty*256-top)+'px';img.onerror=function(){state.fail++;if(state.fail>4)offline.style.display='grid';};tiles.appendChild(img);}markers.innerHTML='';DATA.forEach(function(x){if(/country centroid/i.test(x.precision)&&z>6)return;var q=project(+x.lat,+x.lon,z),dx=q.x-c.x;if(dx>d.w/2)dx-=256*n;if(dx<-d.w/2)dx+=256*n;var dy=q.y-c.y,px=d.w/2+dx,py=d.h/2+dy;if(px<-20||py<-20||px>d.w+20||py>d.h+20)return;var b=document.createElement('button');b.type='button';b.className='nww-map-marker'+(x.id===p.id?' is-selected':'')+(px>d.w*.66?' nww-label-left':'');b.style.left=px+'px';b.style.top=py+'px';b.dataset.nwwMapId=x.id;b.setAttribute('aria-label',x.name);b.innerHTML='<span>'+esc(x.name)+'<br>'+esc(x.country)+' · '+esc(x.kind)+'</span>';markers.appendChild(b);});}
    function zoom(d){var z=clamp(state.zoom+d,2,15);if(z!==state.zoom){state.zoom=z;draw();}}function fly(x){state.lat=+x.lat;state.lon=+x.lon;state.zoom=zoomFor(x);draw();}root.querySelectorAll('[data-nww-map-action]').forEach(function(b){b.onclick=function(e){e.preventDefault();var a=b.dataset.nwwMapAction;if(a==='in')zoom(1);else if(a==='out')zoom(-1);else fly(p);};});root.addEventListener('pointerdown',function(e){var marker=e.target.closest&&e.target.closest('[data-nww-map-id]');if(marker){e.preventDefault();e.stopPropagation();select(marker.dataset.nwwMapId);return;}if(e.target.closest('.nww-map-controls,.nww-map-attrib'))return;var c=project(state.lat,state.lon,state.zoom);state.drag={x:e.clientX,y:e.clientY,cx:c.x,cy:c.y};root.setPointerCapture(e.pointerId);root.classList.add('is-dragging');});root.addEventListener('pointermove',function(e){if(!state.drag)return;center(state.drag.cx-(e.clientX-state.drag.x),state.drag.cy-(e.clientY-state.drag.y));draw();});function end(e){if(!state.drag)return;state.drag=null;root.classList.remove('is-dragging');try{root.releasePointerCapture(e.pointerId);}catch(x){}}root.addEventListener('pointerup',end);root.addEventListener('pointercancel',end);draw();if(window.ResizeObserver){var ro=new ResizeObserver(draw);ro.observe(root);}return{state:state,draw:draw,fly:fly};}
  function bars(key,n){var m=countBy(key),a=Object.keys(m).map(function(k){return[k,m[k]];}).sort(function(x,y){return y[1]-x[1]||x[0].localeCompare(y[0]);}).slice(0,n||6),max=a.length?a[0][1]:1;return'<div class="nww-bars">'+a.map(function(x){return'<div class="nww-bar"><label title="'+esc(x[0])+'">'+esc(x[0])+'</label><span class="nww-track"><i style="width:'+Math.round(x[1]/max*100)+'%"></i></span><b>'+x[1]+'</b></div>';}).join('')+'</div>';}
  function sourceCard(p){return'<div class="nww-source-card"><div class="nww-source-top"><label>Latest verified public record · checked '+esc(p.checked)+'</label><a href="'+esc(p.source)+'" target="_blank" rel="noreferrer">'+esc(p.sourceLabel)+' ↗</a></div><p>'+esc(p.latest)+'</p></div>';}
  function brief(p){var prefix=/country centroid/i.test(p.precision)?'This is a country-level uranium resource record, not a facility. ':'';return prefix+p.name+' is recorded as '+p.status.toLowerCase()+'. The analyst-relevant facts are its '+p.kind.toLowerCase()+' role, '+p.capacity+', and '+p.material.toLowerCase()+'. Coordinate precision is explicitly '+p.precision.toLowerCase()+'. Verify any operational change against '+p.sourceLabel+' and the responsible national authority; do not infer readiness, inventory, output, or safeguards conclusions that the cited public record does not state.';}
  function facts(p){return'<div class="nww-facts"><div class="nww-fact"><label>Operator / authority</label><strong>'+esc(p.operator)+'</strong></div><div class="nww-fact"><label>Public facility scope</label><strong>'+esc(p.scope)+'</strong></div><div class="nww-fact"><label>Material / activity</label><strong>'+esc(p.material)+'</strong></div><div class="nww-fact"><label>Safeguards / oversight</label><strong>'+esc(p.safeguards)+'</strong></div></div>';}
  function overview(p){return'<div data-nww-view="overview">'+mapHtml(p)+'<section class="nww-section"><div class="nww-sechead"><b>Facility at a glance</b><span>Source fields · not inferred scores</span></div><div class="nww-kpis"><div class="nww-kpi"><label>Recorded status</label><strong title="'+esc(p.status)+'">'+esc(p.status)+'</strong><span>Latest public classification</span></div><div class="nww-kpi"><label>Published capacity</label><strong title="'+esc(p.capacity)+'">'+esc(p.capacity)+'</strong><span>Retains source qualifier</span></div><div class="nww-kpi"><label>Facility class</label><strong title="'+esc(p.kind)+'">'+esc(p.kind)+'</strong><span>'+esc(p.region)+'</span></div><div class="nww-kpi"><label>Coordinate precision</label><strong title="'+esc(p.precision)+'">'+esc(p.precision)+'</strong><span>'+esc(coordText(p))+'</span></div></div></section><section class="nww-section">'+sourceCard(p)+'</section><section class="nww-section"><div class="nww-brief"><label>AI analyst brief</label><p>'+esc(brief(p))+'</p></div></section></div>';}
  function materialView(p){return'<div data-nww-view="material" hidden><section class="nww-section"><div class="nww-sechead"><b>Reactor and material position</b><span>Published scope only</span></div>'+facts(p)+'</section><section class="nww-section"><div class="nww-sechead"><b>Global uranium resource context</b><span>NEA / IAEA Red Book 2024 · position at 1 Jan 2023</span></div><div class="nww-reserve"><div><label>Identified recoverable</label><strong>7.9345M tU</strong><span>Below USD 260/kgU</span></div><div><label>Lower-cost identified</label><strong>5.9257M tU</strong><span>Below USD 130/kgU</span></div><div><label>Country reports</label><strong>62</strong><span>48 government-submitted</span></div></div></section><section class="nww-section"><div class="nww-sechead"><b>Facility classes in register</b><span>Public records</span></div>'+bars('kind',7)+'</section></div>';}
  function safeguardsView(p){return'<div data-nww-view="safeguards" hidden><section class="nww-section"><div class="nww-sechead"><b>Safeguards and oversight</b><span>No inferred compliance finding</span></div><div class="nww-list"><div class="nww-list-row"><label>Selected record</label><span>'+esc(p.safeguards)+'</span></div><div class="nww-list-row"><label>Verification rule</label><span>Use the current IAEA Safeguards Implementation Report, facility-specific agreements and the national regulator. Absence of a public entry is not evidence of absence or non-compliance.</span></div><div class="nww-list-row"><label>Coordinate rule</label><span>'+esc(p.precision)+'. Exact zoom is reserved for publicly documented civilian sites; strategic locations are generalized.</span></div><div class="nww-list-row"><label>Analytical boundary</label><span>No readiness score, proliferation probability, secret inventory, throughput estimate or vulnerability assessment is generated.</span></div></div></section><section class="nww-section">'+sourceCard(p)+'</section></div>';}
  function networkView(p){return'<div data-nww-view="network" hidden><section class="nww-section"><div class="nww-sechead"><b>Portfolio distribution</b><span>'+DATA.length+' public-source records</span></div>'+bars('region',7)+'</section><section class="nww-section"><div class="nww-sechead"><b>Strategic force context</b><span>SIPRI estimates · January 2026</span></div><div class="nww-reserve"><div><label>Global inventory</label><strong>12,187</strong><span>Estimated warheads</span></div><div><label>Military stockpiles</label><strong>9,745</strong><span>Potentially available</span></div><div><label>Deployed</label><strong>4,012</strong><span>Missiles and aircraft</span></div></div></section><section class="nww-section"><div class="nww-sechead"><b>Analytical role</b><span>Selected public record</span></div><div class="nww-source-card"><p>'+esc(p.role)+'</p></div></section></div>';}
  function analyticsHtml(p){return'<div class="nww-a"><header class="nww-head"><i class="nww-mark"></i><div><h2>'+esc(p.name)+'</h2><p>'+esc(p.kind)+' · '+esc(p.country)+' · '+esc(p.region)+'</p></div><span class="nww-status" data-tone="'+tone(p.status,p.kind)+'">'+esc(p.status)+'</span></header><nav class="nww-nav" role="tablist"><button class="active" data-nww-tab="overview">Overview</button><button data-nww-tab="material">Reactor & material</button><button data-nww-tab="safeguards">Safeguards</button><button data-nww-tab="network">Network & sources</button></nav>'+overview(p)+materialView(p)+safeguardsView(p)+networkView(p)+'<details class="nww-method"><summary>Coverage, sources and coordinate policy</summary><p>This interface is a public-source analytical register, not a claim to enumerate undisclosed facilities. Power-reactor data is grounded in IAEA PRIS; research reactors in RRDB; civilian fuel-cycle facilities in NFCIS; uranium resource context in the NEA/IAEA Red Book; and aggregate strategic-force figures in SIPRI. Exact public coordinates are shown for declared civilian sites. Sensitive or strategic facilities use public approximate or generalized coordinates, clearly labelled. Records never expose access-control, vulnerability or operational-security details.</p></details><div class="nww-actions"><button type="button" class="nww-ai" data-nww-chat>Research this facility</button><span class="nww-method-note">The selected record attaches internally; AI Research opens visually clean.</span></div></div>';}
  function cardFor(p){return{title:p.name,feature:FEATURE,tier:'geopolitics',tierLabel:'Global',bucket:'Strategic Assets',csv:'niy_nuclear_watch_public',__nwwId:p.id,source:p.source,fields:{Facility:p.name,Country:p.country,Region:p.region,'Facility class':p.kind,'Recorded status':p.status,'Coordinate precision':p.precision,Coordinates:coordText(p),'Operator / authority':p.operator,'Public scope':p.scope,'Published capacity':p.capacity,'Material / activity':p.material,'Safeguards / oversight':p.safeguards,'Latest public record':p.latest,'Source checked':p.checked,'Primary source':p.source,'Analytical role':p.role}};}
  function ensureCard(p){if(!window.NiyAI||!Array.isArray(window.NiyAI.cards)||!p)return;for(var i=window.NiyAI.cards.length-1;i>=0;i--)if(window.NiyAI.cards[i]&&window.NiyAI.cards[i].csv==='niy_nuclear_watch_public')window.NiyAI.cards.splice(i,1);if(typeof window.NiyAI.addCard==='function')window.NiyAI.addCard(cardFor(p));}
  function resetAI(){if(window.NiyAI){if(typeof window.NiyAI.clear==='function')window.NiyAI.clear();else if(Array.isArray(window.NiyAI.cards))window.NiyAI.cards.splice(0);}try{if(typeof globalAiMessages!=='undefined'&&Array.isArray(globalAiMessages))globalAiMessages.splice(0);}catch(e){}var pane=document.querySelector('#detail .niy-pane-ai');if(pane){var c=pane.querySelector('.niy-ai-context');if(c){c.innerHTML='';c.hidden=true;}var l=pane.querySelector('.niy-ai-log');if(l)l.innerHTML='<div class="niy-ai-empty"><div class="niy-ai-empty-t">Ask Nuclear Watch</div></div>';}}
  function bindFeedRows(root){if(!root)return;root.querySelectorAll('[data-nww-id]').forEach(function(r){if(r.dataset.nwwBound)return;var open=function(e){if(!isActive())return;e.preventDefault();e.stopPropagation();select(r.dataset.nwwId);};r.addEventListener('pointerdown',open,true);r.addEventListener('mousedown',open,true);r.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){open(e);}},true);r.dataset.nwwBound='1';});}
