  function ensureFeed(){var body=document.querySelector('#detail .niy-col-feed .niy-col-body');if(!body||!isActive())return;var host=document.getElementById('nwwNuclearFeed');if(!host){host=document.createElement('div');host.id='nwwNuclearFeed';host.innerHTML=feedHtml();body.insertBefore(host,body.firstChild);host.querySelectorAll('.nww-search,.nww-select').forEach(function(c){c.addEventListener('input',filter);c.addEventListener('change',filter);});}bindFeedRows(host);paint();}
  function filter(){var h=document.getElementById('nwwNuclearFeed');if(!h)return;var q=(h.querySelector('.nww-search').value||'').toLowerCase().trim(),k=h.querySelector('.nww-kind').value,r=h.querySelector('.nww-region').value,s=h.querySelector('.nww-status-filter').value;var list=DATA.filter(function(p){var text=[p.name,p.country,p.region,p.kind,p.status,p.operator,p.material,p.scope,p.capacity].join(' ').toLowerCase();return(!q||text.indexOf(q)>-1)&&(!k||p.kind===k)&&(!r||p.region===r)&&(!s||p.status===s);});h.querySelector('tbody').innerHTML=feedRows(list);h.querySelector('[data-nww-count]').textContent=list.length;bindFeedRows(h);paint();}
