  function workspace(name,clean){var d=document.getElementById('detail');if(!d||!isActive())return;name=name==='ai'?'ai':'analytics';if(name==='ai'&&clean)resetAI();d.classList.remove('nww-mode-ai','nww-mode-analytics');d.classList.add('nww-mode-'+name);document.querySelectorAll('#detail .niy-mode').forEach(function(b){var on=b.dataset.mode===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',on?'true':'false');});var a=document.querySelector('#detail .niy-pane-analytics'),i=document.querySelector('#detail .niy-pane-ai');if(a)a.hidden=name==='ai';if(i)i.hidden=name!=='ai';if(name==='analytics')render();else{ensureCard(selected);labels();var input=document.querySelector('#detail .niy-pane-ai .niy-ai-input');if(input)setTimeout(function(){input.focus();},40);}}
